package org.sleepwell.app;
import android.app.NotificationManager;import android.content.*;import android.os.SystemClock;
/** Explicit owned expiry and protected system lifecycle only; never enables a rule. */
public final class TrackingDndReceiver extends BroadcastReceiver {
 static final String EXPIRE="org.sleepwell.app.TRACKING_DND_EXPIRE";
 @Override public void onReceive(Context c,Intent intent){if(intent==null)return;String action=intent.getAction();if(EXPIRE.equals(action)){String token=intent.getStringExtra("token");long deadline=intent.getLongExtra("deadline",-1);if(token==null||token.isEmpty()||deadline<0)return;PendingResult pending=goAsync();TrackingDndRuntime.Job job=TrackingDndRuntime.get(c);job.submit(()->{try{job.owner.expire(token,deadline,SystemClock.elapsedRealtime(),TrackingDndRuntime.boot(job.app));}finally{pending.finish();}},false);}else if(Intent.ACTION_BOOT_COMPLETED.equals(action)||Intent.ACTION_MY_PACKAGE_REPLACED.equals(action)){PendingResult pending=goAsync();TrackingDndRuntime.Job job=TrackingDndRuntime.get(c);job.submit(()->{try{if(job.settings.touchedBefore())job.owner.recover(TrackingService::ownsDnd,TrackingDndRuntime.boot(job.app),SystemClock.elapsedRealtime());}finally{pending.finish();}},false);}else if(NotificationManager.ACTION_AUTOMATIC_ZEN_RULE_STATUS_CHANGED.equals(action)){String id=intent.getStringExtra(NotificationManager.EXTRA_AUTOMATIC_ZEN_RULE_ID);int status=intent.getIntExtra(NotificationManager.EXTRA_AUTOMATIC_ZEN_RULE_STATUS,NotificationManager.AUTOMATIC_RULE_STATUS_UNKNOWN);if(id==null)return;TrackingDndRuntime.Job job=TrackingDndRuntime.get(c);job.submit(()->{TrackingDndLease lease=job.settings.read();if(lease==null||!id.equals(lease.rule))return;boolean disabled=status==NotificationManager.AUTOMATIC_RULE_STATUS_REMOVED||status==NotificationManager.AUTOMATIC_RULE_STATUS_DISABLED&&!job.port.enabled(lease.rule,lease.token);if(android.os.Build.VERSION.SDK_INT>=35&&status==NotificationManager.AUTOMATIC_RULE_STATUS_DEACTIVATED&&job.port instanceof TrackingDndAndroid){TrackingDndAndroid actual=(TrackingDndAndroid)job.port;disabled=actual.notifications.getAutomaticZenRuleState(id)!=android.service.notification.Condition.STATE_TRUE;}if(disabled){job.settings.enabled(false);job.owner.stop(lease.run);job.settings.error("The tracking DND rule was disabled or removed in Android.");}},false);}}
}
